import { readFileSync } from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { type MigrateDownArgs, type MigrateUpArgs, sql } from '@payloadcms/db-postgres'

// Schema for connecting every page to the CMS. The DDL lives in the .sql file next to
// this one (generated by migration/schema-sql.mts from payload.config) and is idempotent,
// so it is safe on a database where parts of it already exist.
const dirname = path.dirname(fileURLToPath(import.meta.url))

export async function up({ db }: MigrateUpArgs): Promise<void> {
  await db.execute(sql.raw(readFileSync(path.join(dirname, '20261001_000000_cms_connect.sql'), 'utf8')))
}

export async function down(_: MigrateDownArgs): Promise<void> {
  // Additive only; nothing to undo safely (dropping tables would delete edited content).
}
